import {escapeHTML as e,publicPath} from './lib.mjs';
import {articles,practices,mixedMaterials,topics,routes,questions,bookList,lesson,config,createdAt} from './content/index.mjs';
import courseModules from './content/course.mjs';
import {renderForum,forumTopics} from './forum.mjs';
import {routeGuides,bookGuides} from './content/journeys.mjs';
import {schoolIdentity,platformHeader,authDialog,accountContent,firstModuleContent} from './platform.mjs';

export function templates({base,origin,published=false}) {
 const u=path=>base+path.replace(/^\//,'');
 const icon=(name)=>{const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',share:'<path d="M12 15V3m-4 4 4-4 4 4M5 12v8h14v-8"/>',book:'<path d="M12 6C8 3 4 4 3 5v15c3-2 6-2 9 0 3-2 6-2 9 0V5c-3-2-6-2-9 1v14"/>',check:'<path d="m5 12 4 4L19 6"/>',play:'<path d="m9 5 11 7-11 7z"/>',circle:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="1"/><path d="m3 6 9 7 9-7"/>'};return `<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true">${paths[name]||paths.circle}</svg>`;};
 const topic=id=>topics.find(t=>t.id===id);
 const article=slug=>articles.find(x=>x.slug===slug);
 const practice=slug=>practices.find(x=>x.slug===slug);
 const path=item=>publicPath(item,base);
 const localProgress=()=>`<section class="local-tools" data-personal-progress hidden><h2>Продолжить с места остановки</h2><p>Ваши отметки и записи на этом устройстве.</p><ul class="progress-links">${practices.map(item=>`<li data-progress-key="practice:${item.slug}" hidden><a href="${path(item)}">${e(item.title)}</a><span data-progress-label></span></li>`).join('')}<li data-progress-key="lesson:pauza-i-vybor" hidden><a href="${u('learn/pauza-i-vybor/')}">Открытый модуль: пауза и выбор</a><span data-progress-label></span></li></ul></section>`;
 const art=(name,cls='')=>`<div class="artwork art-${e(name)} ${e(cls)}" aria-hidden="true"></div>`;
 const eyebrow=text=>`<p class="eyebrow">${text}</p>`;
 const button=(href,label,cls='',attrs='')=>`<a class="button ${cls}" href="${e(href)}" ${attrs}>${label}</a>`;
 const paragraphs=text=>text.split('\n\n').map(t=>`<p>${e(t)}</p>`).join('');
 const tag=item=>`<span class="tag">${item.type==='practice'?'Практика':e(topic(item.topic).short)}</span>`;
 const card=(item,{small=false}={})=>`<article class="material-card ${small?'compact':''}" data-item="${e(item.type+':'+item.slug)}" data-topic="${e(item.topic)}" data-format="${e(item.type)}"><a class="card-cover" href="${path(item)}" tabindex="-1" aria-hidden="true">${art(item.art)}</a><div class="card-copy"><div class="card-meta">${tag(item)}<span>${item.minutes} мин${item.type==='article'?' чтения':' практики'}</span></div><h3><a href="${path(item)}">${e(item.title)}</a></h3><p>${e(item.description)}</p><button class="save-card icon-button" aria-haspopup="dialog" aria-controls="school-auth" data-save="${item.type}:${item.slug}" aria-label="Сохранить: ${e(item.title)}" aria-pressed="false">${icon('bookmark')}</button></div></article>`;
 const sectionTitle=(kicker,title,link,label)=>`<div class="section-head"><div>${eyebrow(kicker)}<h2>${title}</h2></div>${link?`<a class="text-link" href="${e(link)}">${label}</a>`:''}</div>`;
 const routeCards=()=>`<div class="route-grid">${routes.map(r=>`<a class="route-card" href="${u('start/'+r.slug+'/')}"><span class="route-symbol symbol-${r.art}" aria-hidden="true"></span><h3>${e(r.title)}</h3><p>${e(r.description)}</p><span class="route-meta">2 статьи · практика · первый модуль</span></a>`).join('')}</div>`;
 const qRows=(items)=>items.map((q,i)=>`<details class="question" data-question-category="${e(q.category)}"><summary><span><span class="eyebrow">${e(q.category)}</span>${e(q.q)}</span><span class="plus" aria-hidden="true">+</span></summary><div class="answer"><p>${e(q.a)}</p><a class="text-link" href="${path(article(q.slug))}">Разобрать подробнее</a></div></details>`).join('');
 const next=(title,text,href,label)=>`<aside class="next-step"><span class="next-symbol" aria-hidden="true">${icon('book')}</span><div>${eyebrow('Следующий шаг')}<h3>${e(title)}</h3><p>${e(text)}</p>${button(href,label,'gold')}</div></aside>`;
 const membership=(title,description)=>`<aside class="membership-step"><div><p class="eyebrow">Обучение в школе</p><h3>Код Смотрителя</h3><p>Последовательная программа: объяснения, видеоуроки и задания. Посмотрите содержание и формат обучения.</p></div><div class="membership-actions">${button(u('course/'),'Программа обучения','gold')}${button(u('learn/first-module/'),'Первый модуль')}</div></aside>`;
 const footer=()=>`<footer class="footer"><div class="footer-top"><div><a class="wordmark school-brand" href="${u('')}" aria-label="Zeland — школа трансерфинга, главная">${schoolIdentity()}</a><p>Идеи, к которым возвращаются.<br>Практика, которая начинается в жизни.</p></div><div><h3>Исследовать</h3><a href="${u('library/')}">Библиотека</a><a href="${u('practices/')}">Практики</a><a href="${u('books/')}">Книги</a><a href="${u('questions/')}">Форум и ответы</a></div><div><h3>Продолжить</h3><a href="${u('learn/')}">Обучение</a><a href="${u('course/')}">Код Смотрителя</a><a href="${u('about/')}">О проекте</a><a href="${config.app}">Учебный кабинет</a></div><div><h3>Связаться</h3><a href="${u('contact/')}">Задать вопрос команде</a><a href="${u('privacy/')}">Данные и приватность</a><a href="${u('terms/')}">Условия использования</a><button class="text-link" data-consent-open>Настройки статистики</button></div></div><div class="footer-bottom"><p>© 2026 Zeland · Трансерфинг — авторский эзотерический подход Вадима Зеланда. Материалы журнала — изложение и упражнения для самостоятельного наблюдения.</p></div></footer>`;
 const header=active=>platformHeader(base,active);
 const crumb=(items)=>`<nav class="breadcrumbs" aria-label="Навигационная цепочка"><a href="${u('')}">Главная</a>${items.map(([text,href])=>`<span aria-hidden="true">/</span>${href?`<a href="${e(href)}">${e(text)}</a>`:`<span aria-current="page">${e(text)}</span>`}`).join('')}</nav>`;
 const pageIntro=(label,title,description)=>`<div class="page-intro">${eyebrow(label)}<h1>${title}</h1><p>${description}</p></div>`;
 const cookies=()=>`<div class="consent-panel" id="consent-panel" hidden role="dialog" aria-modal="true" aria-labelledby="consent-title"><div class="consent-inner"><h2 id="consent-title">Статистика — по вашему выбору</h2><p>С согласия включим Google Analytics для событий просмотра и переходов. Содержимое заметок и поисковых запросов не передаётся. Закладки и прогресс работают без статистики.</p><div class="button-row"><button class="button gold" data-consent="yes">Разрешить статистику</button><button class="button" data-consent="no">Без статистики</button></div><a href="${u('privacy/')}">Подробнее о данных</a><button class="icon-button consent-close" aria-label="Закрыть настройки" data-consent-close>${icon('close')}</button></div></div>`;
 function shell({title,description,active='',body,route='',reading=false,noindex=false,schema}) {
  const canonical=origin+u(route); const metadata={title:title==='Главная'?'Zeland — школа трансерфинга':title+' — Zeland',description};
  return `<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(metadata.title)}</title><meta name="description" content="${e(description)}"><meta name="robots" content="${!published||noindex?'noindex,nofollow':'index,follow'}"><meta name="theme-color" content="#121110"><link rel="canonical" href="${e(canonical)}"><meta property="og:type" content="${reading?'article':'website'}"><meta property="og:locale" content="ru_RU"><meta property="og:site_name" content="Zeland"><meta property="og:title" content="${e(metadata.title)}"><meta property="og:description" content="${e(description)}"><meta property="og:url" content="${e(canonical)}"><meta property="og:image" content="${e(origin+u('assets/pendulum.webp'))}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="${u('assets/favicon.svg')}" type="image/svg+xml"><link rel="stylesheet" href="${u('assets/fonts.css')}"><link rel="stylesheet" href="${u('assets/site.css')}"><link rel="stylesheet" href="${u('assets/platform.css')}"><link rel="stylesheet" href="${u('assets/depth.css')}"><link rel="stylesheet" href="${u('assets/simple.css')}"><script type="module" src="${u('assets/client.mjs')}"></script>${schema?`<script type="application/ld+json">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script>`:''}</head><body data-base="${base}" data-page="${e(route)}" data-analytics-id="G-TBKC4J9949" ${reading?'class="reading-page"':''}>${header(active)}<main id="main" tabindex="-1">${body}</main>${footer()}<div class="toast" role="status" aria-live="polite" hidden></div>${cookies()}${authDialog(base)}</body></html>`;
 }
 function home(){return shell({title:'Главная',description:'Школа трансерфинга Zeland: статьи, практики, книги, форум и обучение «Код Смотрителя».',body:`
<section class="hero school-home-hero"><div class="hero-copy">${eyebrow('Zeland')}<h1>Школа<br><em>трансерфинга</em></h1><p class="school-home-subtitle">Статьи и практики от Вадима Зеланда</p><p>Разбирайтесь в идеях, пробуйте упражнения и обсуждайте то, что важно вам. Для последовательной работы — обучение «Код Смотрителя».</p><div class="button-row">${button(u('library/'),'Читать статьи')}${button(u('course/'),'Обучение','gold')}</div></div><figure class="hero-human"><picture><source media="(max-width:600px)" srcset="${u('assets/school-embrace-mobile.webp')}"><img src="${u('assets/school-embrace.webp')}" alt="Иллюстрация: тёплые объятия на сцене" width="1536" height="1024" fetchpriority="high"></picture></figure></section>
<section class="school-learning-banner"><img src="${u('assets/kod-smotritelya.webp')}" width="1500" height="838" alt="Код Смотрителя" loading="lazy"><div>${eyebrow('Обучение в школе')}<h2>Код Смотрителя</h2><p>От отдельных наблюдений к системе: видеоуроки, объяснения и задания. Знакомство начинается с первого модуля.</p><div class="button-row">${button(u('course/'),'Программа обучения','gold')}${button(u('learn/first-module/'),'Первый модуль')}</div></div></section>
<section class="section home-library">${sectionTitle('Библиотека школы','Статьи о трансерфинге',u('library/'),'Все 24 статьи')}<nav class="home-topic-links" aria-label="Темы статей">${topics.map(t=>`<a href="${u('library/?topic='+t.id)}">${e(t.title)}</a>`).join('')}</nav><div class="card-grid home-card-grid">${['snizit-vazhnost','svoia-tsel','zerkalo-mira'].map(slug=>card(article(slug))).join('')}</div></section>
<section class="section home-practices">${sectionTitle('Попробовать сейчас','Практики на каждый день',u('practices/'),'Все 6 практик')}<div class="practice-shortlist">${['pauza-smotritelya','svoya-tsel','plan-b'].map(slug=>{const x=practice(slug);return `<a href="${path(x)}">${art(x.art)}<div><span class="eyebrow">${x.minutes} мин · практика</span><h3>${e(x.title)}</h3><p>${e(x.description)}</p></div></a>`}).join('')}</div></section>
<section class="section home-forum">${sectionTitle('Обсуждения и вопросы','Форум школы',u('questions/'),'Все 32 темы')}<p class="section-note">Отношения, работа, цели и применение принципов в обычной жизни.</p><div class="home-forum-list">${forumTopics.slice(0,3).map(t=>`<a href="${u('questions/#topic-'+t.id)}"><span class="eyebrow">${e(t.category)}</span><h3>${e(t.title)}</h3><span class="text-link">Открыть обсуждение</span></a>`).join('')}</div></section>
<section class="section home-start">${sectionTitle('Для первого знакомства','С чего начать',u('start/'),'Выбрать маршрут')}${routeCards()}</section>
<section class="school-discovery" aria-label="Книги и школа"><a class="discovery-books" href="${u('books/')}"><div>${eyebrow('Библиотека первоисточников')}<h2>Пять ступеней.<br><em>Один новый взгляд.</em></h2><p>Книги Вадима Зеланда: с чего начать и к каким идеям вернуться.</p><span class="discovery-link">Открыть путеводитель по книгам</span></div><div class="discovery-shelf" aria-hidden="true">${[1,2,3,4,5].map(n=>`<img src="${u('assets/book-'+n+'.jpg')}" alt="" width="200" height="316" loading="lazy">`).join('')}</div><span class="discovery-caption">Трансерфинг реальности · классическая серия</span></a><a class="discovery-school" href="${u('about/')}"><div class="discovery-identity" aria-hidden="true">${schoolIdentity()}</div><div>${eyebrow('О школе')}<h2>От идеи —<br>к личной практике.</h2><p>Вадим Зеланд, книги автора школы и пространство для изучения трансерфинга.</p></div><div class="discovery-bottom"><span>Читать. Пробовать. Обсуждать.</span><span class="discovery-link">Познакомиться со школой</span></div></a></section>`});}
 function library({saved=false,practiceOnly=false}={}){

  const items=practiceOnly?practices:mixedMaterials;
  const route=saved?'saved/':practiceOnly?'practices/':'library/';
  return shell({title:saved?'Мои материалы':practiceOnly?'Практики':'Библиотека',description:saved?'Сохранённые статьи и практики вашего аккаунта.':practiceOnly?'Шесть коротких практик для наблюдения за вниманием, выбора и повседневных действий.':'Статьи и практики о трансерфинге. Поиск по полному тексту, рубрики и тематические маршруты.',route,active:practiceOnly?'practices':'library',noindex:saved,body:`${crumb([[saved?'Мои материалы':practiceOnly?'Практики':'Библиотека']])}${pageIntro(saved?'Ваша полка':practiceOnly?'От идеи к опыту':'Читайте в своём темпе',saved?'То, к чему хочется вернуться':practiceOnly?'Практики на каждый день':'Статьи о трансерфинге',saved?'Ваша подборка связана с аккаунтом и доступна после входа на разных устройствах.':practiceOnly?'Выберите одно упражнение. Найдите для него обычную ситуацию. Заметьте, что получилось.':'24 статьи и 6 практик. Выберите тему или найдите ответ на свой вопрос.')}${saved?'<section data-account-guest class="saved-account-gate"><h2>Войдите, чтобы открыть свою полку</h2><p data-account-status role="status">Проверяем вход…</p><button class="button gold" data-auth-open="login">Войти</button> <button class="button" data-auth-open="register">Создать аккаунт</button></section>':''}<div id="library" ${saved?'data-account-member hidden':''} data-saved-only="${saved}" data-practice-only="${practiceOnly}"><form class="search-form" role="search"><label for="search">Поиск по названиям и полному тексту</label><div class="search-field">${icon('search')}<input id="search" name="q" type="search" placeholder="Например: маятники, своя цель, важность" autocomplete="off" maxlength="200"><button class="button" type="submit">Найти</button></div></form><div class="filters"><div class="topic-filters" role="group" aria-label="Тема"><button class="filter active" data-topic-filter="all" aria-pressed="true">Все темы</button>${topics.map(t=>`<button class="filter" data-topic-filter="${t.id}" aria-pressed="false">${e(t.short)}</button>`).join('')}</div>${!practiceOnly?'<label class="format-label">Формат<select id="format"><option value="all">Все форматы</option><option value="article">Статьи</option><option value="practice">Практики</option></select></label>':''}</div><div class="results-meta"><p id="result-count" role="status">${saved?'Ваши сохранённые материалы':items.length+' материалов'}</p><button class="text-link" data-clear-filters>Сбросить фильтры</button></div><p class="search-error" hidden>Полнотекстовый поиск временно недоступен. Поиск по названиям и описаниям продолжает работать.</p><div class="card-grid library-grid">${items.map(x=>card(x)).join('')}</div><div class="empty-state" hidden><span>${icon('book')}</span><h2>${saved?'На вашей полке пока пусто':'Пока ничего не нашли'}</h2><p>${saved?'Нажмите значок закладки у понравившегося материала. Он появится здесь.':'Попробуйте другой запрос или уберите фильтры. Например: «внимание» или «цель».'}</p>${button(u('library/'),'Исследовать библиотеку','gold')}</div></div>${saved?localProgress():''}${saved?'<section class="local-tools"><h2>Ваши записи — с вами</h2><p>Экспорт содержит прежние локальные закладки, отметки и личные заметки этого браузера; закладки аккаунта хранятся отдельно. Храните файл у себя. Импорт добавит записи из выбранного файла и обновит совпадающие заметки.</p><div class="button-row"><button class="button" data-export>Экспортировать мои данные</button><label class="button">Импортировать файл<input type="file" accept="application/json,.json" id="import-data" class="sr-only"></label></div></section>':''}${next('Не знаете, с чего начать?','Три коротких маршрута: знакомство, меньше напряжения или своё направление.',u('start/'),'Выбрать маршрут')}`});
 }
 function material(item){
  const isPractice=item.type==='practice';
  const sections=isPractice?item.steps:item.sections;
  const format=isPractice?'Практики':'Библиотека';
  const route=(isPractice?'practices/':'articles/')+item.slug+'/';
  const key=item.type+':'+item.slug;
  const discussions=forumTopics.filter(t=>t.article===item.slug||isPractice&&(t.practice===item.slug||item.related.includes(t.article))).slice(0,3);
  const book=bookGuides.find(b=>b.articles.includes(item.slug))||bookGuides.find(b=>b.practice===item.slug)||bookGuides[0];
  const suggestedRoute=routes.find(r=>r.items.some(([,slug])=>slug===item.slug))||routes.find(r=>r.slug===(item.topic==='choice'?'svoy-put':item.topic==='attention'?'menshe-napryazheniya':'poznakomitsya'));
  const controls=`<div class="reader-controls"><button class="button small" aria-haspopup="dialog" aria-controls="school-auth" data-save="${key}" aria-pressed="false">${icon('bookmark')}<span>Сохранить</span></button><button class="button small" data-share>${icon('share')}<span>Поделиться</span></button><button class="button small" data-reading-theme aria-pressed="false">${icon('sun')}<span>Светлый фон</span></button></div>`;
  const notes=isPractice?`<section class="notebook" id="notebook"><h2>Рабочая запись</h2><p>Запишите то, что произошло в вашей попытке. Можно начать с коротких вопросов и вернуться к ним позже.</p><ul>${item.questions.map(q=>`<li>${e(q)}</li>`).join('')}</ul><button class="text-link" type="button" data-note-template="${e(item.workbook.fields.join('\n\n'))}">Добавить структуру записи</button><label for="personal-note">Личная запись к практике</label><textarea id="personal-note" data-note="${key}" rows="5" maxlength="12000" placeholder="Что заметили и что хотите попробовать дальше?"></textarea><p class="local-note">Только в этом браузере. Запись не отправляется команде. На общем устройстве другие пользователи браузера могут её прочитать.</p><div class="button-row"><button class="button" data-save-note="${key}">Сохранить заметку</button><button class="button gold" data-complete="${key}" aria-pressed="false">Отметить практику выполненной</button></div><p class="completion-note">Отметка означает вашу запись о попытке, а не подтверждённый результат.</p></section>`:'';
  return shell({title:item.title,description:item.description,route,active:isPractice?'practices':'library',reading:true,schema:published?{'@context':'https://schema.org','@type':isPractice?'LearningResource':'Article',headline:item.title,description:item.description,datePublished:createdAt,dateModified:createdAt,author:{'@type':'Organization',name:'Редакция Zeland'},mainEntityOfPage:origin+u(route)}:null,body:`<progress class="reading-progress" max="100" value="0" aria-label="Положение на странице"></progress>${crumb([[format,u(isPractice?'practices/':'library/')],[topic(item.topic).title,u('library/?topic='+item.topic)],[item.title]])}<header class="article-header">${eyebrow((isPractice?'Практика':item.readingFormat)+' · '+e(topic(item.topic).title))}<h1>${e(item.title)}</h1><p class="article-deck">${e(item.description)}</p><div class="article-byline"><span class="editor-mark">Z</span><div><strong>Редакция Zeland</strong><span>${item.minutes} мин${isPractice?' на практику':' чтения'}</span></div></div>${controls}${isPractice?`<a class="button gold practice-start-link" href="#section-1">Начать практику · ${item.minutes} мин</a>`:''}</header><div class="article-cover">${art(item.art)}</div><div class="reader-layout"><aside class="toc"><details><summary>Содержание материала</summary><ol>${sections.map(([title],i)=>`<li><a href="#section-${i+1}">${e(title)}</a></li>`).join('')}${isPractice?'<li><a href="#notebook">Ваши наблюдения</a></li>':''}</ol></details></aside><article class="article-body" data-material="${key}">${isPractice?`<div class="practice-goal"><span class="eyebrow">Для чего</span><p>${e(item.goal)}</p></div><p class="lead">${e(item.intro)}</p><details class="practice-preparation"><summary>Когда пригодится и как подготовиться</summary><h2>Когда пригодится</h2><p>${e(item.workbook.situation)}</p><h3>Перед началом</h3><p>${e(item.preparation)}</p><details class="practice-short"><summary>Если есть только полминуты <span aria-hidden="true">+</span></summary><p>${e(item.workbook.shortVersion)}</p></details></details><div class="timer-panel" data-timer-seconds="${item.minutes*60}"><span class="timer-display" role="timer" aria-label="Оставшееся время">${String(item.minutes).padStart(2,'0')}:00</span><div><strong>Время для себя</strong><p>Таймер необязателен. Идите в своём темпе.</p></div><button class="button small" data-timer-start>Начать</button><button class="text-link" data-timer-reset>Сбросить</button></div>`:''}${sections.map(([title,text],i)=>`<section id="section-${i+1}">${isPractice?`<span class="step-label">Шаг ${i+1}</span>`:''}<h2>${e(title)}</h2>${isPractice?paragraphs(text.split('\n\n')[0])+(text.includes('\n\n')?`<details class="step-explanation"><summary>Подробнее о шаге</summary>${paragraphs(text.split('\n\n').slice(1).join('\n\n'))}</details>`:''):paragraphs(text)}${isPractice?`<label class="practice-step-check"><input type="checkbox" data-practice-step="${key}:${i}">Этот шаг пройден</label>`:''}</section>`).join('')}${isPractice?`<details class="practice-example"><summary>Пример заполнения <span aria-hidden="true">+</span></summary><dl>${item.example.map(([label,value])=>`<div><dt>${e(label)}</dt><dd>${e(value)}</dd></div>`).join('')}</dl></details><details class="practice-troubleshooting"><summary>Если не получается и когда вернуться</summary><h2>Если не получается</h2><p>${e(item.pitfall)}</p><h3>Что считать завершением</h3><p>${e(item.workbook.checkpoint)}</p><h3>Когда вернуться</h3><p>${e(item.workbook.returnWhen)}</p><p>${e(item.after)}</p></details><div class="pull-note"><p>${e(item.finish)}</p></div>${notes}`:`<div class="pull-note"><p>Вернитесь к одной ситуации из своего дня. Какое небольшое действие теперь выглядит доступным?</p></div>${next(practice(item.practice).title,'Попробуйте идею на собственном примере. Небольшое упражнение с последовательностью шагов.',path(practice(item.practice)),'Перейти к практике')}`}<section class="sources"><h2>Об этом материале</h2><p>Автор идей трансерфинга — Вадим Зеланд. Объяснения, бытовые примеры и упражнения в этом материале подготовлены редакцией школы.</p><p>Для знакомства с первоисточниками: ${config.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${e(s.title)}</a>`).join('; ')}. Трансерфинг рассматривается как авторский эзотерический подход.</p><a class="text-link" href="${u('books/#book-'+book.id)}">Читать вместе с книгой «${e(bookList[book.id-1].title)}»</a><details class="article-edition"><summary>Сведения о материале <span aria-hidden="true">+</span></summary><p>Подготовлено и обновлено <time datetime="${item.date}">21 ноября 2026</time>. Редакция Zeland. Время чтения рассчитано по объёму текста; вопросы и упражнения можно проходить в своём темпе.</p></details></section><section class="article-discussion"><p class="eyebrow">Продолжить разговор</p><h2>Узнаёте свою ситуацию?</h2>${discussions.length?`<div class="related-discussions">${discussions.map(t=>`<a href="${u('questions/#topic-'+t.id)}"><span>${e(t.category)}</span><strong>${e(t.title)}</strong></a>`).join('')}</div>`:'<p>Найдите близкий вопрос в общей ленте обсуждений.</p>'}<div class="button-row">${button(u('questions/'),'Все обсуждения')}<button class="button" data-auth-open="register" data-auth-reason="forum">Задать свой вопрос</button></div></section>${membership('От отдельной идеи — к последовательной практике.','В первом модуле «Кода Смотрителя» собраны объяснения и задания. Единый аккаунт свяжет обучение, ваши материалы и обсуждения.')}<a class="reading-route-link" href="${u('start/'+suggestedRoute.slug+'/')}">Продолжить по маршруту: ${e(suggestedRoute.title)}</a></article></div><section class="section">${sectionTitle('Продолжить исследование','Связанные материалы')}<div class="related-grid">${item.related.map(slug=>card(article(slug))).join('')}</div></section>`});
 }
 function start(){return shell({title:'С чего начать',description:'Выберите вопрос и пройдите связанный маршрут: объяснение, пример, практика, обсуждение и первый модуль.',route:'start/',active:'start',body:`${crumb([['С чего начать']])}${pageIntro('Три маршрута','С чего начать','Вам не нужно заранее знать термины или проходить диагностику. Выберите знакомую ситуацию — дальше будет понятная последовательность.')}<div class="start-questions">${routes.map(r=>`<a href="${u('start/'+r.slug+'/')}"><span>${e(routeGuides[r.slug].question)}</span><strong>${e(r.title)}</strong><small>${e(routeGuides[r.slug].result)}</small></a>`).join('')}</div><section class="section">${sectionTitle('Как устроен маршрут','Прочитать. Попробовать. Вернуться.')}<div class="start-method">${[['Разобраться','Одна идея и конкретный пример из обычной жизни.'],['Попробовать','Небольшое упражнение с шагами и рабочей записью.'],['Уточнить','Обсуждение похожей ситуации или личный вопрос команде.'],['Продолжить','Первый модуль для тех, кому подходит последовательное обучение.']].map(([t,d])=>`<div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section><div class="reading-advice"><h2>Если подход уже знаком</h2><p>Необязательно возвращаться к началу. Выберите конкретный вопрос в библиотеке, упражнение или обсуждение.</p><div class="button-row">${button(u('library/'),'Найти материал')}${button(u('books/'),'Читать вместе с книгами')}${button(u('questions/'),'Найти обсуждение')}</div></div>${membership('Собрать свои наблюдения в систему.','Первый модуль — следующий шаг после знакомства. Изучите программу и выберите удобный темп.')}`});}
 function routePage(r){const items=r.items.map(([type,slug])=>type==='article'?article(slug):practice(slug));const guide=routeGuides[r.slug];const minutes=items.reduce((n,x)=>n+x.minutes,0);return shell({title:r.title,description:r.description,route:'start/'+r.slug+'/',active:'start',body:`${crumb([['С чего начать',u('start/')],[r.title]])}${pageIntro('Ваш маршрут',e(r.title),e(guide.question))}<div class="route-overview"><p><strong>Что вы соберёте</strong>${e(guide.result)}</p><p><strong>Около ${minutes} минут чтения и практики</strong>${e(guide.pace)}</p></div><div class="route-layout"><aside class="route-art">${art(r.art)}<p>Каждый шаг отвечает на свой вопрос. Остановиться и вернуться позже — тоже часть вашего темпа.</p><a class="text-link" href="${u('books/#book-'+guide.book)}">Связать с чтением книги</a></aside><ol class="route-steps">${items.map((item,i)=>`<li><span class="step-label">Шаг ${i+1} · ${item.type==='article'?'Статья':'Практика'} · ${item.minutes} мин</span><h2><a href="${path(item)}">${e(item.title)}</a></h2><p>${e(guide.why[i])}</p><div class="route-reflection"><strong>Вопрос к себе</strong><p>${e(guide.reflect[i])}</p></div><div class="button-row">${button(path(item),'Открыть материал','small')}<button class="text-link" data-route-complete="route:${r.slug}:${i}" aria-pressed="false">Отметить шаг пройденным</button></div></li>`).join('')}<li><span class="step-label">Сопоставить с другим взглядом</span><h2>Обсудить свою попытку</h2><p>В общей теме можно увидеть похожий вопрос и разные способы его разобрать. Для собственного сообщения понадобится аккаунт.</p>${button(u('questions/#topic-'+guide.forum),'Открыть связанную тему')}</li><li><span class="step-label">Продолжить последовательно</span><h2>Первый модуль «Кода Смотрителя»</h2><p>«Иллюзия отражения»: шесть уроков и заданий, которые связывают наблюдение, выбор и действие.</p>${button(u('learn/first-module/'),'Перейти к первому модулю','gold')}</li></ol></div><p class="local-note">Отметки маршрута сохраняются в этом браузере. Для синхронизации с будущим кабинетом потребуется единый аккаунт.</p>`});}
 function questionsPage(){return shell({title:'Форум и вопросы',description:'Темы о принципах, практике и повседневном опыте. Демонстрация будущего форума Zeland.',route:'questions/',active:'questions',body:`${crumb([['Форум']])}<div class="forum-intro">${pageIntro('Сообщество школы','Форум школы','Обсуждайте принципы, практики и ситуации из жизни. Читать можно без аккаунта; для ответа понадобится вход.')}</div>${renderForum(base)}<section class="section">${sectionTitle('Ответы редакции','Коротко о частых вопросах')}<div class="questions-list">${qRows(questions)}</div></section>`});}
 function books(){return shell({title:'Книги и основы трансерфинга',description:'Пять ступеней классического трансерфинга: что читать, какие вопросы задать себе и как связать книгу с практикой.',route:'books/',active:'books',body:`${crumb([['Книги']])}${pageIntro('Вадим Зеланд · классическая серия','Читать глубже.<br><em>Замечать в своей жизни.</em>','Пять ступеней — последовательное знакомство с языком автора. Рядом с каждой книгой — подборка объяснений, практика и вопрос для собственного наблюдения.')}<nav class="book-index" aria-label="Книги серии">${bookList.map((b,i)=>`<a href="#book-${i+1}">${e(b.title)}</a>`).join('')}</nav><div class="book-list">${bookList.map((b,i)=>{const g=bookGuides[i];return `<article class="book-row" id="book-${g.id}"><div class="book-image"><img src="${u('assets/'+b.cover)}" alt="Обложка книги «${e(b.title)}», Вадим Зеланд" width="${b.width}" height="${b.height}" loading="lazy" decoding="async"></div><div>${eyebrow(e(b.subtitle))}<h2>${e(b.title)}</h2><p>${e(g.description)}</p><div class="book-question"><span>Вопрос для чтения</span><strong>${e(g.question)}</strong></div><details class="book-companion"><summary>Читать вместе с библиотекой <span aria-hidden="true">+</span></summary><p>${e(g.task)}</p><ul>${g.articles.map(slug=>`<li><a href="${path(article(slug))}">${e(article(slug).title)}</a><span>${article(slug).minutes} мин</span></li>`).join('')}</ul><div class="button-row">${button(path(practice(g.practice)),'Связанная практика','small')}${button(u('questions/#topic-'+g.forum),'Обсудить вопрос','small')}</div></details></div></article>`;}).join('')}</div><div class="reading-advice"><h2>Одна глава — три записи</h2><div class="book-reading-method"><p><strong>Мысль автора</strong>Как вы поняли понятие? Если смысл неясен, сохраните вопрос к первоисточнику.</p><p><strong>Свой пример</strong>В каком эпизоде идея становится понятнее? Не нужно подгонять любое событие под объяснение.</p><p><strong>Одна попытка</strong>Какое действие вы хотите проверить? Вернитесь к главе уже с опытом.</p></div><p>Порядок классической серии и доступные издания — в <a href="https://zelands.ru/knigi-o-transerfinge/" target="_blank" rel="noopener noreferrer">каталоге автора</a>. Подборки выше — редакционное сопровождение чтения; полные тексты книг здесь не размещаются.</p></div>${membership('От чтения — к последовательной практике.','Первый модуль поможет познакомиться с форматом объяснений и заданий. Книги остаются первоисточником авторского подхода.')}`});}
 function account(){return shell({title:'Личный кабинет',description:'Профиль, обучение и сохранённые материалы школы Zeland.',route:'account/',noindex:true,body:`${crumb([['Личный кабинет']])}${accountContent(base)}`});}
 function firstModule(){return shell({title:'Первый модуль — Иллюзия отражения',description:'Шесть уроков и заданий первого модуля Код Смотрителя. Программа и будущий доступ через единый аккаунт App Zeland.',route:'learn/first-module/',active:'learn',body:`${crumb([['Обучение',u('learn/')],['Первый модуль']])}${firstModuleContent(base)}`});}
 function learn(){return shell({title:'Обучение',description:'Первый модуль Код Смотрителя, самостоятельный вводный урок и полная программа практикума.',route:'learn/',active:'learn',body:`${crumb([['Обучение']])}${pageIntro('Школа трансерфинга','Обучение','«Код Смотрителя» — последовательная программа с видеоуроками и заданиями. Начните с первого модуля или изучите полную программу.')}<div class="learning-feature"><img src="${u('assets/kod-smotritelya.webp')}" width="1500" height="838" alt="Код Смотрителя — действующая обложка курса"><div>${eyebrow('Знакомство с практикумом')}<h2>Первый модуль.<br><em>Иллюзия отражения.</em></h2><p>Шесть уроков о Смотрителе, выборе и важности. Каждый связан с заданием для самостоятельного наблюдения.</p>${button(u('learn/first-module/'),'Посмотреть содержание','gold')}<p class="local-note">Бесплатный доступ после регистрации запланирован. Оригинальные уроки подключим вместе с App Zeland.</p></div></div><div class="learning-grid"><article class="learning-card">${art('practice-pause')}${eyebrow('Уже доступно · без аккаунта')}<h2>Пауза. Наблюдение. Выбор.</h2><p>Самостоятельный редакционный урок: объяснение, практика и личная запись. Около 12 минут в своём темпе.</p>${button(u('learn/pauza-i-vybor/'),'Открыть самостоятельную пробу')}</article><article class="learning-card"><img class="learning-cover" src="${u('assets/kod-smotritelya.webp')}" width="1500" height="838" loading="lazy" alt="Код Смотрителя">${eyebrow('Полная программа')}<h2>Код Смотрителя</h2><p>Четыре основных этапа, видеоуроки, тексты и задания. Программа, форматы участия и условия обучения.</p>${button(u('course/'),'Изучить программу')}</article></div><p class="local-note">Самостоятельная проба доступна без аккаунта. Первый модуль относится к программе «Код Смотрителя»; доступ к оригинальным урокам появится после подключения кабинета.</p>`});}
 function lessonPage(){return shell({title:lesson.title,description:lesson.description,route:'learn/pauza-i-vybor/',active:'learn',reading:true,body:`${crumb([['Обучение',u('learn/')],[lesson.title]])}<header class="article-header">${eyebrow('Открытый редакционный модуль · 12 минут')}<h1>Пауза.<br><em>Наблюдение. Выбор.</em></h1><p class="article-deck">Небольшой законченный опыт: заметить привычный импульс и выбрать одно действие.</p><p class="local-note">Без регистрации. Это самостоятельный вводный модуль журнала; прогресс хранится на этом устройстве.</p></header><div class="lesson-layout" data-lesson="pauza-i-vybor"><aside class="lesson-nav"><h2>Ваш маршрут</h2><ol><li><a href="#lesson-idea">Понять идею</a></li><li><a href="#lesson-practice">Попробовать паузу</a></li><li><a href="#lesson-action">Выбрать действие</a></li></ol><progress id="lesson-progress" max="3" value="0" aria-label="Пройденные шаги модуля"></progress><p id="lesson-count">0 из 3 шагов отмечено</p></aside><article class="article-body"><section id="lesson-idea"><span class="step-label">Шаг 1 · понять</span><h2>Реакция — это ещё не решение</h2><p>В обычном разговоре событие, объяснение и действие часто сливаются. Приходит короткое сообщение, появляется мысль «мной недовольны», и вы уже оправдываетесь. Между этими частями можно заметить небольшую паузу.</p><p>Смотритель — удобный образ для такого наблюдения. Здесь не требуется безупречное спокойствие. Достаточно назвать, что произошло и что хочется сделать автоматически.</p><div class="lesson-example"><strong>Пример</strong><p>Вам предлагают дополнительную задачу. Привычный ответ — согласиться сразу. Возможный новый шаг: «Дай мне проверить сроки, я отвечу после обеда».</p></div><label class="step-check"><input type="checkbox" data-lesson-step="idea">Я разобрался с идеей</label></section><section id="lesson-practice"><span class="step-label">Шаг 2 · попробовать</span><h2>Три небольших движения внимания</h2><ol><li>Остановитесь и посмотрите на три предмета вокруг.</li><li>Назовите факт и свой импульс отдельно.</li><li>Спросите: какое действие сейчас соответствует моей задаче?</li></ol><p>Возьмите безопасный бытовой эпизод. Если пауза не появилась, рассмотрите ситуацию после события. Не нужно считать это провалом.</p><a class="text-link" href="${path(practice('pauza-smotritelya'))}">Подробная практика с таймером</a><label class="step-check"><input type="checkbox" data-lesson-step="practice">Я попробовал упражнение</label></section><section id="lesson-action"><span class="step-label">Шаг 3 · перенести в жизнь</span><h2>Какое действие вы выберете?</h2><p>Завершите три предложения: «Когда происходит… я обычно… В следующий раз попробую…». Выбирайте небольшое действие, которое действительно доступно.</p><label for="lesson-note">Ваша личная запись</label><textarea id="lesson-note" data-note="lesson:pauza-i-vybor" rows="6" maxlength="12000" placeholder="Когда… Обычно я… В следующий раз…"></textarea><p class="local-note">Запись остаётся в этом браузере и не отправляется команде. На общем устройстве её могут прочитать другие пользователи браузера.</p><button class="button" data-save-note="lesson:pauza-i-vybor">Сохранить запись</button><label class="step-check"><input type="checkbox" data-lesson-step="action">Я выбрал следующее действие</label></section><div class="lesson-finish" hidden><h2>Маршрут завершён.</h2><p>Вы отметили три шага. Вернитесь к записи после следующего похожего эпизода и посмотрите, что изменилось в вашем действии.</p></div>${next('Если хочется последовательной практики','В полной программе — видеоуроки, тексты, задания и возможность задавать вопросы.',u('course/'),'Посмотреть «Код Смотрителя»')}<div class="button-row">${button(u('saved/'),'Мои записи и материалы')}${button(u('contact/'),'Задать вопрос')}</div></article></div>`});}
 function course(){return shell({title:'Практикум «Код Смотрителя»',description:'Программа практикума, форматы участия и путь к учебному кабинету. Актуальные данные с zeland.it.com.',route:'course/',active:'learn',body:`${crumb([['Обучение',u('learn/')],['Код Смотрителя']])}<section class="course-hero"><div>${eyebrow('Практикум по принципам трансерфинга')}<h1>Код<br><em>Смотрителя</em></h1><p>Замечать привычный сценарий.<br>Возвращать внимание.<br>Действовать осознаннее.</p><div class="button-row">${button('#programme','Посмотреть программу','gold')}${button(u('learn/first-module/'),'Первый модуль')}</div></div><div class="real-course-cover"><img src="${u('assets/kod-smotritelya.webp')}" alt="Код Смотрителя — обложка программы" width="1500" height="838" loading="lazy"></div></section><section class="section"><div class="course-description"><h2>Понятный маршрут.<br>Ваш собственный темп.</h2><p>Для тех, кто хочет перейти от отдельных идей к последовательной работе со своим запросом. Внутри — видео, текстовые объяснения и задания на учебной платформе. Можно изучать материал в удобном темпе и задавать вопросы по ходу.</p></div><div class="video-block" data-video="${e(config.video)}" data-poster="${e(config.videoPoster)}"><button class="video-trigger"><span class="video-play">${icon('play')}</span><span><strong>Посмотреть вводное видео</strong><small>1 мин 15 сек · с текущего сайта практикума</small></span></button><p class="local-note">Видео загрузится с Cloudinary после нажатия.</p></div></section><section class="section" id="programme">${sectionTitle('Содержание программы','У каждого шага есть своё место')}<div class="programme">${courseModules.map(m=>`<details ${m.id===1?'open':''}><summary><span><span class="eyebrow">${e(m.subtitle)}</span>${e(m.title)}</span><span class="plus" aria-hidden="true">+</span></summary><div class="programme-body"><p>${e(m.intro)}</p>${m.lessons.map(l=>`<div class="programme-lesson"><h3>${e(l.title)}</h3><p>${e(l.meaning)}</p><p class="local-note">${e(l.practice)}</p><p class="programme-benefit"><strong>В центре внимания:</strong> ${e(l.benefit)}</p></div>`).join('')}<p class="programme-result">${e(m.result)}</p></div></details>`).join('')}</div><p class="local-note">Программа сверена с zeland.it.com 21 ноября 2026. Дополнительные материалы и доступные уроки показывает учебная платформа.</p></section><section class="section" id="formats">${sectionTitle('Форматы участия','Выберите глубину сопровождения')}<div class="pricing-grid"><article class="price-card">${eyebrow('В собственном темпе')}<h3>Курс с поддержкой</h3><p class="price">$95 <span>/ 7 900 ₽</span></p><ul><li>Все основные модули, видео и задания</li><li>Постоянный доступ к материалам</li><li>Последовательное открытие уроков</li><li>Возможность задавать вопросы по программе</li></ul>${button(config.course+'#pricing','Проверить условия и присоединиться','gold','data-event="course_enquiry"')}<p class="local-note">Перейдёте на текущую страницу практикума. Оплату и выдачу доступа сопровождает команда.</p></article><article class="price-card">${eyebrow('Более глубокая работа')}<h3>Персональное сопровождение</h3><p class="price">$600 <span>/ 49 000 ₽</span></p><ul><li>Всё из курса с поддержкой</li><li>Шесть месяцев работы с личным запросом</li><li>Разбор целей, препятствий и наблюдений</li><li>Индивидуальное общение по договорённости</li></ul>${button(config.course+'#pricing','Обсудить персональный формат','','data-event="course_enquiry"')}<p class="local-note">Формат встреч, ведущий и порядок обратной связи подтверждаются командой до оплаты.</p></article></div><p class="local-note">Цены взяты с текущего сайта на 21 ноября 2026. Уточните условия возврата, состав поддержки и способ оплаты перед покупкой. Автоматическая оплата на этой странице не подключена.</p></section><section class="section how-join"><h2>Как начать обучение</h2><ol><li><strong>Познакомьтесь с форматом.</strong> Изучите содержание первого модуля и программу следующих этапов.</li><li><strong>Уточните условия.</strong> Команда ответит на вопросы и пришлёт способ оплаты в Telegram.</li><li><strong>Получите доступ.</strong> После подтверждения платежа команда выдаёт доступ к App Zeland. Самостоятельная регистрация не нужна.</li></ol><div class="button-row">${button(u('contact/'),'Задать вопрос до покупки','gold')}${button(config.app,'Уже есть доступ — войти')}</div></section>`});}
 function about(){return shell({title:'О проекте и Вадиме Зеланде',description:'Авторская основа, редакционные принципы и формат участия в образовательном ресурсе Zeland.',route:'about/',body:`${crumb([['О проекте']])}${pageIntro('О пространстве','Идеи становятся ближе,<br><em>когда находят место в жизни.</em>','Zeland объединяет объяснения, практики и обучение по темам трансерфинга. Здесь можно разобраться в своём темпе и выбрать следующий шаг.')}<div class="about-layout"><div class="about-author">${art('mirror')}<h2>Вадим Зеланд</h2><p>Автор книг о трансерфинге реальности</p></div><article class="article-body"><h2>Автор и его идеи</h2><p>В основе тематики — книги Вадима Зеланда. Они предлагают особый язык для разговора о внимании, выборе, важности и намерении. Оригинальные тексты и издания можно найти на <a href="https://zelands.ru/" target="_blank" rel="noopener noreferrer">сайте автора</a>.</p><p>Начните с классической серии книг, затем возвращайтесь к отдельным понятиям через статьи, упражнения и вопросы. В каждой части школы можно выбрать своё продолжение: первоисточник, практику или последовательное обучение.</p><h2>Что делает редакция</h2><p>Связывает понятия с обычными ситуациями, готовит объяснения и упражнения, помогает сформулировать вопрос. У материалов указана редакционная ответственность, а комментарии редакции выделены в обсуждениях.</p><h2>Как пользоваться подходом</h2><p>Трансерфинг — авторская эзотерическая система. Метафизические идеи здесь не представлены как доказанные медицинские, финансовые или физические закономерности. Упражнения предлагают наблюдать собственные решения и действия; они не гарантируют внешнего результата.</p><h2>Кто отвечает на вопросы</h2><p>Обращения из журнала направляются команде проекта в Telegram. В учебном кабинете действует существующий порядок выдачи доступа и поддержки.</p>${button(u('contact/'),'Связаться с командой','gold')}</article></div>`});}
 function contact(){return shell({title:'Задать вопрос команде',description:'Подготовьте личный вопрос о материале или практикуме и отправьте его в Telegram.',route:'contact/',body:`${crumb([['Контакты']])}${pageIntro('Личное обращение','Давайте <em>разберёмся.</em>','Уточните идею из статьи, задайте вопрос о практике или узнайте условия участия. Сообщение откроется в личном чате Telegram, а не на публичном форуме.')}<div class="contact-layout"><form id="contact-form" class="contact-form"><label for="question-topic">О чём ваш вопрос?</label><select id="question-topic"><option>О материале библиотеки</option><option>О выполнении практики</option><option>О практикуме «Код Смотрителя»</option><option>Об уже выданном доступе</option></select><label for="question-text">Что вы хотели бы уточнить?</label><textarea id="question-text" rows="6" maxlength="1800" placeholder="Напишите название материала и ваш вопрос…" required></textarea><p class="local-note">Форма ничего не отправляет сама. В Telegram вы увидите текст, сможете изменить его и отправить самостоятельно. Не добавляйте пароли, платёжные данные и коды доступа.</p><button class="button gold" type="submit">Подготовить сообщение в Telegram</button><div id="contact-result" hidden><p>Сообщение подготовлено. Откройте чат и проверьте текст перед отправкой.</p><a class="button gold" id="contact-link" target="_blank" rel="noopener noreferrer">Открыть Telegram</a></div></form><aside><h2>Команда проекта</h2><a class="contact-handle" href="${config.telegram}" target="_blank" rel="noopener noreferrer">@vadim_ze</a><p>Срок ответа заранее не обещается. Если вопрос касается учебного кабинета, укажите логин, но не пароль.</p><h3>Уже есть доступ?</h3><p>Войдите с данными, которые выдала команда.</p>${button(config.app,'Открыть App Zeland')}<h3>Публичные обсуждения</h3><p>Пока не открыты. Можно читать <a href="${u('questions/')}">редакционные вопросы и ответы</a>.</p></aside></div>`});}
 function privacy(){return shell({title:'Данные и приватность',description:'Как журнал хранит локальные записи и использует статистику только с согласия.',route:'privacy/',body:`${crumb([['Данные и приватность']])}${pageIntro('Прозрачно о данных','Ваши записи.<br><em>Ваше решение.</em>','В этой версии нет публичной регистрации. Основные действия доступны без аккаунта.')}<article class="article-body legal"><h2>Сохранённые материалы, заметки и прогресс</h2><p>Новые закладки требуют аккаунта и станут доступны после подключения входа. Заметки и отметки открытых практик сохраняются в localStorage этого браузера. Они не отправляются на сервер App Zeland и не синхронизируются между устройствами. После очистки данных браузера записи могут исчезнуть. На общем устройстве другие пользователи этого браузера могут получить к ним доступ.</p><p>В разделе «Мои материалы» доступен экспорт прежних локальных данных в JSON. Файл содержит личные записи: храните его у себя. Можно удалить данные журнала с этого устройства кнопкой ниже. Аккаунт App Zeland и его данные это действие не затрагивает.</p><button class="button" data-delete-local>Удалить мои данные журнала</button><div id="delete-confirm" hidden><p>Будут удалены только закладки, заметки и прогресс этого журнала в текущем браузере. Сначала можно сделать экспорт.</p><div class="button-row"><button class="button" data-export>Сначала экспортировать</button><button class="button" data-delete-confirm>Удалить локальные данные</button><button class="text-link" data-delete-cancel>Отмена</button></div></div><h2>Статистика</h2><p>Google Analytics подключается только после вашего согласия. Передаются события открытия материалов, использования фильтров, отметок практик, шагов модуля и переходов к программе. Текст заметок, поисковые запросы и текст личного обращения не передаются. Прокрутка означает положение на странице, а не доказанное чтение.</p><p>Если вы разрешите статистику, Google может использовать cookies и технические идентификаторы по своей политике. Можно отключить дальнейшую отправку событий в настройках. Для удаления ранее сохранённых cookies используйте настройки браузера.</p><button class="button" data-consent-open>Изменить выбор статистики</button><h2>Внешние сервисы</h2><p>Telegram открывается после вашего действия; сообщение отправляете вы. Видеофайл с Cloudinary загружается после запуска проигрывателя. К этим сервисам применяются их собственные правила. Сервер размещения может вести технические журналы запросов.</p><h2>Перед публичным запуском</h2><p>Юридическое наименование оператора, контакты для запросов о данных и окончательные условия должны быть подтверждены владельцем. Эта версия предназначена для согласования.</p></article>`});}
 function terms(){return shell({title:'Условия использования',description:'Редакционный статус материалов, порядок доступа к курсу и условия взаимодействия с журналом.',route:'terms/',body:`${crumb([['Условия использования']])}${pageIntro('О формате ресурса','Понятные <em>границы.</em>','Версия для согласования. Обновлено 21 ноября 2026.')}<article class="article-body legal"><h2>Материалы журнала</h2><p>Статьи и упражнения созданы для знакомства с авторским подходом трансерфинга и самостоятельного наблюдения. Они не заменяют медицинскую, психологическую, юридическую или финансовую помощь. Вымышленные бытовые примеры служат объяснению; они не являются историями клиентов или отзывами.</p><h2>Обучение и оплата</h2><p>Журнал не принимает платежи. Состав программы и ориентиры стоимости взяты с текущего сайта практикума. Перед оплатой команда должна подтвердить итоговую цену, валюту, формат поддержки, сроки и условия возврата. Доступ к App Zeland выдаётся по действующему порядку после подтверждения оплаты.</p><h2>Авторство и обсуждения</h2><p>Вадим Зеланд — автор исходного подхода и книг. Объяснения, упражнения и сопровождение чтения подготовлены редакцией. Отправка сообщений на форуме будет доступна после подключения единого аккаунта. Личные обращения не публикуются автоматически.</p><h2>Перед запуском</h2><p>Владельцу необходимо подтвердить сведения об операторе, право использования материалов, окончательные условия покупки и представление команды. Эта страница описывает текущую версию и не подменяет договор продажи курса.</p>${button(u('contact/'),'Уточнить условия','gold')}</article>`});}
 function missing(){return shell({title:'Страница не найдена',description:'Такого материала нет в библиотеке. Найдите нужную статью с помощью поиска.',route:'404/',noindex:true,body:`<section class="empty-page">${eyebrow('Страница не найдена')}<h1>Этой страницы<br><em>здесь пока нет.</em></h1><p>Возможно, адрес изменился. Попробуйте поиск в библиотеке или вернитесь к маршрутам.</p><div class="button-row">${button(u('library/'),'Найти материал','gold')}${button(u('start/'),'С чего начать')}</div></section>`});}
 return {home,library,material,start,routePage,questionsPage,books,learn,lessonPage,firstModule,account,course,about,contact,privacy,terms,missing};
}
